/**
 * Standard A2A Skill definition for capability discovery
 */
export interface A2AAgentSkill {
  id: string;
  name: string;
  description: string;
  tags?: string[];
  inputModes?: ('text/plain' | 'application/json')[];
  outputModes?: ('text/plain' | 'application/json')[];
}

/**
 * Standard A2A Agent Card specification conforming to /.well-known/agent.json
 */
export interface A2AAgentCard {
  name: string;
  description: string;
  url?: string;
  version: string;
  capabilities: {
    streaming: boolean;
    pushNotifications?: boolean;
    stateTransitionHistory?: boolean;
    handoffs?: boolean;
  };
  authentication?: {
    schemes: ('Bearer' | 'OAuth2' | 'MutualTLS' | 'None')[];
  };
  skills: A2AAgentSkill[];
}

/**
 * Configuration for an individual specialist agent in the Swarm
 */
export interface SwarmAgentConfig {
  /**
   * Unique identifier for this agent (e.g. 'triage', 'coder', 'researcher')
   */
  id: string;
  /**
   * Human-readable display name (e.g. 'Code Architect')
   */
  name: string;
  /**
   * High-level role or domain specialization (e.g. 'Senior TypeScript & Security Engineer')
   */
  role: string;
  /**
   * Domain-specific system instructions guiding this agent's actions
   */
  instructions: string;
  /**
   * Optional model override for this agent (e.g. 'gemini-4-flash' for fast triage, 'claude-3-7-sonnet' for deep logic)
   */
  model?: string;
  /**
   * Optional reasoning thinking budget ('auto' or specific token count)
   */
  thinkingBudget?: number | 'auto';
  /**
   * Optional normalized reasoning effort ('none' | 'minimal' | 'low' | 'medium' | 'high' | 'xhigh' | 'max')
   */
  reasoningEffort?: ReasoningEffort;
  /**
   * Optional Gemini 3/4 symbolic thinking level ('minimal' | 'low' | 'medium' | 'high')
   */
  thinkingLevel?: ThinkingLevel;
  /**
   * Specific tool definitions allowed for this agent.
   * If not specified, the agent can access tools registered in the swarm or client.mcp.
   */
  tools?: ToolDefinition[];
  /**
   * List of target agent IDs that this agent is authorized to delegate tasks to.
   */
  handoffs?: string[];
  /**
   * Maximum internal reasoning/tool steps before forcing a handoff or completion.
   * Default: 5
   */
  maxSteps?: number;
  /**
   * A2A skills description for Agent Card discovery
   */
  skills?: A2AAgentSkill[];
  /**
   * Optional micro-economy budget wallet capping spend for this agent.
   */
  wallet?: SwarmAgentWallet;
  /**
   * Optional persona ID referencing a registered persona in AgentPersonaRegistry.
   * If provided, instructions, tool policies, and ephemeral skills are bound to this persona.
   */
  personaId?: string;
}

/**
 * Micro-economy wallet cap for an individual swarm agent.
 */
export interface SwarmAgentWallet {
  maxCostUsd?: number;
  maxTokens?: number;
}

export class AgentWalletExceededError extends Error {
  public readonly agentId: string;
  public readonly limitUsd?: number;
  public readonly currentCostUsd: number;

  constructor(agentId: string, currentCostUsd: number, limitUsd?: number) {
    super(
      `Agent "${agentId}" exceeded allocated budget wallet: $${currentCostUsd.toFixed(4)} (limit: $${limitUsd})`,
    );
    this.name = 'AgentWalletExceededError';
    this.agentId = agentId;
    this.currentCostUsd = currentCostUsd;
    this.limitUsd = limitUsd;
  }
}

export interface ContextMergeOptions {
  /**
   * When true, objects are merged recursively rather than overwritten.
   * Default: true
   */
  deep?: boolean;
  /**
   * How arrays should be merged:
   * - 'union': Deduplicates primitive values, appends objects
   * - 'concat': Appends all items without deduplication
   * - 'replace': Overwrites target array with source array
   * Default: 'union'
   */
  arrayStrategy?: 'union' | 'concat' | 'replace';
  /**
   * Custom conflict resolution callback when a key exists in both targets.
   * Return the resolved value to store in context.
   */
  onConflict?: (
    key: string,
    existingValue: unknown,
    incomingValue: unknown,
  ) => unknown;
}

/**
 * Deeply merges two context dictionaries with recursive object traversal,
 * array union deduplication, and optional conflict handler.
 */
export function deepMergeContext(
  target: Record<string, unknown>,
  source: Record<string, unknown>,
  options: ContextMergeOptions = {},
): Record<string, unknown> {
  const deep = options.deep !== false;
  const arrayStrategy = options.arrayStrategy ?? 'union';
  const result: Record<string, unknown> = { ...target };

  for (const [key, sourceVal] of Object.entries(source)) {
    if (!(key in result)) {
      result[key] = sourceVal;
      continue;
    }

    const targetVal = result[key];

    if (options.onConflict) {
      result[key] = options.onConflict(key, targetVal, sourceVal);
      continue;
    }

    if (Array.isArray(targetVal) && Array.isArray(sourceVal)) {
      if (arrayStrategy === 'union') {
        const set = new Set();
        const merged: unknown[] = [];
        for (const item of [...targetVal, ...sourceVal]) {
          if (item !== null && typeof item === 'object') {
            merged.push(item);
          } else if (!set.has(item)) {
            set.add(item);
            merged.push(item);
          }
        }
        result[key] = merged;
      } else if (arrayStrategy === 'concat') {
        result[key] = [...targetVal, ...sourceVal];
      } else {
        result[key] = sourceVal;
      }
    } else if (
      deep &&
      typeof targetVal === 'object' &&
      targetVal !== null &&
      !Array.isArray(targetVal) &&
      typeof sourceVal === 'object' &&
      sourceVal !== null &&
      !Array.isArray(sourceVal)
    ) {
      result[key] = deepMergeContext(
        targetVal as Record<string, unknown>,
        sourceVal as Record<string, unknown>,
        options,
      );
    } else {
      result[key] = sourceVal;
    }
  }

  return result;
}

/**
 * Shared memory context accessible and mutable by all agents in the swarm
 */
export class SwarmContext {
  private store = new Map<string, unknown>();

  constructor(initialData?: Record<string, unknown>) {
    if (initialData) {
      for (const [key, value] of Object.entries(initialData)) {
        this.store.set(key, value);
      }
    }
  }

  public get<T = unknown>(key: string): T | undefined {
    return this.store.get(key) as T | undefined;
  }

  public set(key: string, value: unknown): this {
    this.store.set(key, value);
    return this;
  }

  public has(key: string): boolean {
    return this.store.has(key);
  }

  public delete(key: string): boolean {
    return this.store.delete(key);
  }

  public clear(): void {
    this.store.clear();
  }

  public getAll(): Record<string, unknown> {
    return Object.fromEntries(this.store.entries());
  }

  /**
   * Merges an incoming context dictionary or another SwarmContext into this instance.
   */
  public merge(
    other: Record<string, unknown> | SwarmContext,
    options?: ContextMergeOptions,
  ): this {
    const incoming = other instanceof SwarmContext ? other.getAll() : other;
    const merged = deepMergeContext(this.getAll(), incoming, options);
    this.store.clear();
    for (const [k, v] of Object.entries(merged)) {
      this.store.set(k, v);
    }
    return this;
  }

  public toPromptSection(): string {
    if (this.store.size === 0) return '';
    return `\n\n[SHARED SWARM CONTEXT]:\n${JSON.stringify(this.getAll(), null, 2)}`;
  }
}

/**
 * Options for instantiating an AgentSwarm
 */
export interface AgentSwarmOptions {
  /**
   * Specialist agent configurations participating in the swarm
   */
  agents: SwarmAgentConfig[];
  /**
   * Initial default agent ID to receive incoming user requests.
   * Defaults to the first agent in the array.
   */
  defaultAgentId?: string;
  /**
   * Maximum allowed delegations between agents to prevent infinite ping-pong loops.
   * Default: 10
   */
  maxHandoffs?: number;
  /**
   * Optional initial shared context values
   */
  initialContext?: Record<string, unknown>;
  /**
   * Global fallback model if agent does not specify one
   */
  defaultModel?: string;
  /**
   * Optional persona registry for persona-bound prompts and ephemeral skills
   */
  personaRegistry?: AgentPersonaRegistry;
  /**
   * Optional callback invoked when an agent output triggers persona drift detection
   */
  onPersonaDrift?: (
    agentId: string,
    personaId: string,
    drift: PersonaDriftResult,
  ) => void;
}

/**
 * Result returned after a Swarm completes its multi-agent orchestration
 */
export interface SwarmResult {
  /**
   * Final text output produced by the completing agent
   */
  content: string;
  /**
   * ID of the agent that produced the final answer
   */
  finalAgentId: string;
  /**
   * Full multi-agent conversation history including tool and handoff messages
   */
  history: ChatMessage[];
  /**
   * Final shared memory state after all turns
   */
  sharedContext: Record<string, unknown>;
  /**
   * Total LLM request steps executed across all agents
   */
  totalSteps: number;
  /**
   * Total number of successful delegations between agents
   */
  totalHandoffs: number;
  /**
   * Step breakdown by agent ID
   */
  agentSteps: Record<string, number>;
  /**
   * Cumulative estimated cost across all agent turns (if usage cost available)
   */
  totalCostUsd: number;
  /**
   * Spend and token breakdown tracked per agent ID
   */
  agentSpendBreakdown?: Record<string, { costUsd: number; tokens: number }>;
  /**
   * Persona drift diagnostics recorded per agent ID when personaRegistry is bound
   */
  personaDrift?: Record<string, PersonaDriftResult>;
  /**
   * Ephemeral skill IDs that expired and were pruned per agent ID during swarm turns
   */
  prunedEphemeralSkills?: Record<string, string[]>;
}

/**
 * Real-time event emitted during a streaming swarm run
 */
export type SwarmStreamEvent =
  | {
      type: 'agent-start';
      agentId: string;
      agentName: string;
      step: number;
      handoffCount: number;
    }
  | {
      type: 'reasoning-delta';
      agentId: string;
      reasoningDelta: string;
      chunk: UnifiedApiStreamChunk;
    }
  | {
      type: 'text-delta';
      agentId: string;
      textDelta: string;
      chunk: UnifiedApiStreamChunk;
    }
  | {
      type: 'tool-call-start';
      agentId: string;
      toolCalls: ToolCall[];
    }
  | {
      type: 'tool-call-result';
      agentId: string;
      toolCalls: ToolCall[];
      results: ChatMessage[];
    }
  | {
      type: 'handoff';
      fromAgentId: string;
      toAgentId: string;
      reason: string;
      contextUpdates?: Record<string, unknown>;
    }
  | {
      type: 'done';
      result: SwarmResult;
    };

/**
 * Task specification for an agent in parallel execution
 */
export interface SwarmParallelAgentTask {
  agentId: string;
  prompt?: string | ChatMessage[];
  contextUpdates?: Record<string, unknown>;
}

/**
 * Options for running multiple swarm agents in parallel
 */
export interface SwarmParallelOptions {
  /**
   * The list of agents to run in parallel.
   * Can be agent IDs or custom task overrides with specific sub-prompts.
   */
  tasks: Array<string | SwarmParallelAgentTask>;
  /**
   * Default prompt given to all tasks if not specified per task.
   */
  prompt?: string | ChatMessage[];
  /**
   * Optional aggregator / synthesizer agent ID that takes the parallel outputs
   * and synthesizes a single definitive response.
   */
  aggregatorAgentId?: string;
  /**
   * Execution mode:
   * - 'all_settled': Wait for all subagents to finish (fail-soft, returns whatever succeeded)
   * - 'strict': Fails immediately if any subagent throws an error
   * Default: 'all_settled'
   */
  mode?: 'all_settled' | 'strict';
  /**
   * Shared initial context passed to all parallel tasks.
   */
  initialContext?: Record<string, unknown>;
  /**
   * Optional timeout per branch in milliseconds.
   */
  timeoutMs?: number;
  /**
   * Optional AbortSignal.
   */
  signal?: AbortSignal;
  /**
   * Strategy for merging context updates produced by concurrent branches:
   * - 'deep-merge': Recursively merges objects and unions arrays (default)
   * - 'last-write-wins': Overwrites keys as branches finish
   */
  contextMergeStrategy?: 'deep-merge' | 'last-write-wins';
  /**
   * Array merging strategy when contextMergeStrategy is 'deep-merge'.
   * Default: 'union'
   */
  arrayStrategy?: 'union' | 'concat' | 'replace';
  /**
   * Custom callback invoked when two branches mutate the same context key.
   */
  onContextConflict?: (
    key: string,
    existingValue: unknown,
    incomingValue: unknown,
    agentId: string,
  ) => unknown;
}

/**
 * Result of an individual parallel agent branch
 */
export interface SwarmParallelBranchResult {
  agentId: string;
  agentName: string;
  status: 'success' | 'error';
  content: string;
  error?: string;
  totalSteps: number;
  costUsd: number;
  history: ChatMessage[];
}

/**
 * Aggregated result returned after parallel swarm execution finishes
 */
export interface SwarmParallelResult {
  content: string;
  branches: SwarmParallelBranchResult[];
  aggregated: boolean;
  aggregatorAgentId?: string;
  totalCostUsd: number;
  totalSteps: number;
  durationMs: number;
  sharedContext: Record<string, unknown>;
}

/**
 * Options for running an Actor-Critic consensus evaluation loop
 */
export interface ActorCriticOptions {
  /**
   * Specialist worker agent ID that generates the initial draft or code solution.
   */
  actorAgentId: string;
  /**
   * Specialist reviewer agent ID that audits and evaluates the submission.
   */
  criticAgentId: string;
  /**
   * The objective task or user prompt to solve.
   */
  task: string | ChatMessage[];
  /**
   * Maximum allowed revision iterations before returning best effort.
   * Default: 3
   */
  maxRevisions?: number;
  /**
   * Minimum score (0.0 to 1.0) required to consider the submission approved.
   * Default: 0.8
   */
  minScore?: number;
  /**
   * Optional initial shared context.
   */
  context?: Record<string, unknown>;
  /**
   * Live callback triggered on each iteration cycle.
   */
  onIteration?: (event: {
    iteration: number;
    actorOutput: string;
    criticFeedback: string;
    approved: boolean;
    score?: number;
  }) => void;
  /**
   * When true (default if distiller is configured), automatically records the
   * initial draft (rejected) and approved final solution (chosen) as a DPO preference pair.
   */
  recordDpo?: boolean;
}

/**
 * Record of an individual iteration in the Actor-Critic loop
 */
export interface ActorCriticRevision {
  iteration: number;
  actorOutput: string;
  criticFeedback: string;
  score?: number;
  status: 'approved' | 'needs_revision';
  timestamp: number;
}

/**
 * Result returned after Actor-Critic loop finishes
 */
export interface ActorCriticResult {
  finalContent: string;
  approved: boolean;
  totalRevisions: number;
  revisions: ActorCriticRevision[];
  totalCostUsd: number;
  actorAgentId: string;
  criticAgentId: string;
  history: ChatMessage[];
  sharedContext: Record<string, unknown>;
}

/**
 * Options for multi-model tournament and voting consensus
 */
export interface TournamentOptions {
  /**
   * The task or prompt given to all participating agents
   */
  task: string | ChatMessage[];
  /**
   * List of agent IDs participating in the tournament deliberation
   */
  agentIds: string[];
  /**
   * Voting strategy: 'borda' (ranked choice), 'majority' (most votes), or 'weighted' (agent capability weights)
   * Default: 'borda'
   */
  votingStrategy?: TournamentVotingStrategy;
  /**
   * Optional custom weights per agent ID (e.g. { 'lead_architect': 2.0 })
   */
  weights?: Record<string, number>;
  /**
   * Cosine similarity threshold for grouping submissions into consensus clusters (default: 0.58)
   */
  similarityThreshold?: number;
  /**
   * Optional synthesizer agent ID to formulate a final unified response resolving consensus and dissent
   */
  synthesizerAgentId?: string;
  /**
   * Optional shared initial context
   */
  context?: Record<string, unknown>;
  /**
   * When true (default if distiller is configured), automatically records the winning
   * solution as chosen and the top dissenting view as rejected in client.distiller
   */
  recordDpo?: boolean;
  /**
   * Optional progress callback during tournament execution phases
   */
  onVoteProgress?: (progress: {
    phase: 'fan_out' | 'clustering' | 'tallying' | 'synthesis';
    completedAgents?: number;
    totalAgents?: number;
  }) => void;
}

/**
 * Result of a multi-model tournament consensus deliberation
 */
export interface TournamentResult {
  winningSolution: string;
  winningAgentId: string;
  strategy: TournamentVotingStrategy;
  confidence: number;
  clusters: TournamentCluster[];
  dissentingViews: DissentingView[];
  scores: Record<string, TournamentAgentScore>;
  totalCostUsd: number;
  totalSubmissions: number;
  synthesizedContent?: string;
  submissions: Record<string, { content: string; costUsd: number }>;
  history: ChatMessage[];
  sharedContext: Record<string, unknown>;
}

/**
 * In-Process Multi-Agent Swarm Orchestrator
 */
export class AgentSwarm {
  private client: SinapsClient;
  private agents = new Map<string, SwarmAgentConfig>();
  private defaultAgentId: string;
  private maxHandoffs: number;
  private defaultModel?: string;
  public readonly personaRegistry?: AgentPersonaRegistry;
  private onPersonaDrift?: AgentSwarmOptions['onPersonaDrift'];

  constructor(client: SinapsClient, options: AgentSwarmOptions) {
    this.client = client;
    this.maxHandoffs = options.maxHandoffs ?? 10;
    this.defaultModel = options.defaultModel;
    this.personaRegistry = options.personaRegistry;
    this.onPersonaDrift = options.onPersonaDrift;

    if (!options.agents || options.agents.length === 0) {
      throw new Error('AgentSwarm requires at least one specialist agent.');
    }

    for (const agent of options.agents) {
      this.agents.set(agent.id, agent);
    }

    this.defaultAgentId = options.defaultAgentId || options.agents[0].id;
    if (!this.agents.has(this.defaultAgentId)) {
      throw new Error(
        `Default agent ID "${this.defaultAgentId}" is not in the registered agents list.`,
      );
    }
  }

  /**
   * Get an agent by its ID
   */
  public getAgent(id: string): SwarmAgentConfig | undefined {
    return this.agents.get(id);
  }

  /**
   * List all registered swarm agents
   */
  public listAgents(): SwarmAgentConfig[] {
    return Array.from(this.agents.values());
  }

  /**
   * Export A2A Agent Cards for all registered agents in this swarm
   */
  public exportAgentCards(baseUrl?: string): A2AAgentCard[] {
    return Array.from(this.agents.values()).map((agent) => ({
      name: agent.name,
      description: `${agent.role}: ${agent.instructions.slice(0, 200)}`,
      url: baseUrl
        ? `${baseUrl.replace(/\/$/, '')}/agents/${agent.id}`
        : undefined,
      version: SINAPSAI_VERSION,
      capabilities: {
        streaming: true,
        handoffs: (agent.handoffs && agent.handoffs.length > 0) || false,
      },
      skills: agent.skills || [
        {
          id: `${agent.id}-core`,
          name: agent.name,
          description: agent.role,
          tags: [agent.id, 'sinapsai-swarm'],
          inputModes: ['text/plain', 'application/json'],
          outputModes: ['text/plain', 'application/json'],
        },
      ],
    }));
  }

  /**
   * Synthesize handoff tool definitions for an agent
   */
  private getHandoffTools(agent: SwarmAgentConfig): ToolDefinition[] {
    if (!agent.handoffs || agent.handoffs.length === 0) {
      return [];
    }

    const tools: ToolDefinition[] = [];
    for (const targetId of agent.handoffs) {
      const target = this.agents.get(targetId);
      if (!target) continue;

      tools.push({
        type: 'function',
        function: {
          name: `transfer_to_${target.id}`,
          description: `Delegate the task to ${target.name} (${target.role}). ${target.instructions.slice(0, 140)}`,
          parameters: {
            type: 'object',
            properties: {
              reason: {
                type: 'string',
                description:
                  'Detailed explanation of why you are transferring this task',
              },
              context_updates: {
                type: 'object',
                description:
                  'Key-value state updates to commit to shared memory before handoff',
                additionalProperties: true,
              },
            },
            required: ['reason'],
          },
        },
      });
    }

    return tools;
  }

  /**
   * Compile full tool list for an agent, combining its specific tools, client.mcp tools, and handoff tools
   */
  private compileAgentTools(agent: SwarmAgentConfig): ToolDefinition[] {
    const handoffTools = this.getHandoffTools(agent);
    const mcpTools = this.client.mcp.toUnifiedTools();

    const baseTools = agent.tools
      ? [...agent.tools, ...handoffTools]
      : [...mcpTools, ...handoffTools];

    const personaId = agent.personaId;
    const registry = this.personaRegistry;
    if (personaId && registry) {
      return baseTools.filter(
        (t) =>
          t.function.name.startsWith('transfer_to_') ||
          registry.isToolAllowed(personaId, t.function.name),
      );
    }

    return baseTools;
  }

  /**
   * Run the multi-agent swarm to completion (non-streaming)
   */
  public async run(options: {
    messages?: ChatMessage[];
    task?: string;
    initialAgentId?: string;
    context?: Record<string, unknown>;
  }): Promise<SwarmResult> {
    const context = new SwarmContext(options.context);
    let activeAgentId = options.initialAgentId || this.defaultAgentId;
    let handoffCount = 0;
    let totalSteps = 0;
    const agentSteps: Record<string, number> = {};
    const agentSpendBreakdown: Record<
      string,
      { costUsd: number; tokens: number }
    > = {};
    const personaDrift: Record<string, PersonaDriftResult> = {};
    const prunedEphemeralSkills: Record<string, string[]> = {};
    const startCost = this.client.getMetrics().estimatedCostUsd;
    const history: ChatMessage[] = options.messages
      ? [...options.messages]
      : [];
    if (options.task && history.length === 0) {
      history.push({ role: 'user', content: options.task });
    }

    while (handoffCount <= this.maxHandoffs) {
      const agent = this.agents.get(activeAgentId);
      if (!agent) {
        throw new Error(`Active agent "${activeAgentId}" not found in Swarm.`);
      }

      agentSteps[activeAgentId] = (agentSteps[activeAgentId] || 0) + 1;
      totalSteps++;

      // Build effective system instructions injected with shared context
      let baseInstructions = agent.instructions;
      if (agent.personaId && this.personaRegistry) {
        baseInstructions = this.personaRegistry.buildSystemPrompt(
          agent.personaId,
          agent.instructions,
        );
      }
      const systemContent = `${baseInstructions}\n\nYou are specialist: ${agent.name} (${agent.role}).${context.toPromptSection()}`;

      // Filter out existing system prompts and prepend active agent's system prompt
      const stepMessages: ChatMessage[] = [
        { role: 'system', content: systemContent },
        ...history.filter((m) => m.role !== 'system'),
      ];

      const tools = this.compileAgentTools(agent);

      const req: CreateChatCompletionRequest = {
        model: agent.model || this.defaultModel || 'default',
        messages: stepMessages,
        tools: tools.length > 0 ? tools : undefined,
        thinkingBudget: agent.thinkingBudget,
        reasoningEffort: agent.reasoningEffort,
        thinkingLevel: agent.thinkingLevel,
      };

      const response = (await this.client.chat.completions.create(
        req,
      )) as UnifiedApiResponse;

      const choice = response.choices[0];
      if (!choice) {
        break;
      }

      // Track micro-economy wallet spend per agent
      const usage = response.usage as
        | {
            promptTokens?: number;
            completionTokens?: number;
            totalTokens?: number;
            prompt_tokens?: number;
            completion_tokens?: number;
            total_tokens?: number;
          }
        | undefined;
      const promptTokens = usage?.promptTokens ?? usage?.prompt_tokens ?? 0;
      const completionTokens =
        usage?.completionTokens ?? usage?.completion_tokens ?? 0;
      const stepTokens =
        usage?.totalTokens ??
        usage?.total_tokens ??
        promptTokens + completionTokens;
      const stepCost =
        (response as { costUsd?: number }).costUsd ??
        promptTokens * 0.0000015 + completionTokens * 0.000002;

      if (!agentSpendBreakdown[activeAgentId]) {
        agentSpendBreakdown[activeAgentId] = { costUsd: 0, tokens: 0 };
      }
      agentSpendBreakdown[activeAgentId].costUsd = Number(
        (agentSpendBreakdown[activeAgentId].costUsd + stepCost).toFixed(6),
      );
      agentSpendBreakdown[activeAgentId].tokens += stepTokens;

      if (agent.wallet) {
        if (
          agent.wallet.maxCostUsd !== undefined &&
          agentSpendBreakdown[activeAgentId].costUsd > agent.wallet.maxCostUsd
        ) {
          throw new AgentWalletExceededError(
            activeAgentId,
            agentSpendBreakdown[activeAgentId].costUsd,
            agent.wallet.maxCostUsd,
          );
        }
        if (
          agent.wallet.maxTokens !== undefined &&
          agentSpendBreakdown[activeAgentId].tokens > agent.wallet.maxTokens
        ) {
          throw new AgentWalletExceededError(
            activeAgentId,
            agentSpendBreakdown[activeAgentId].tokens,
            agent.wallet.maxTokens,
          );
        }
      }

      const msg = choice.message;
      history.push(msg);

      // Evaluate persona lifecycle: consume ephemeral skill turn and inspect response drift
      if (agent.personaId && this.personaRegistry) {
        const turnInfo = this.personaRegistry.consumeTurn(agent.personaId);
        if (turnInfo.prunedSkills.length > 0) {
          prunedEphemeralSkills[activeAgentId] = [
            ...(prunedEphemeralSkills[activeAgentId] || []),
            ...turnInfo.prunedSkills,
          ];
        }
        const msgText =
          typeof msg.content === 'string'
            ? msg.content
            : Array.isArray(msg.content)
              ? (msg.content as ContentPart[])
                  .filter((p) => p.type === 'text')
                  .map((p) => p.text)
                  .join('')
              : '';
        if (msgText) {
          const drift = this.personaRegistry.detectDrift(
            agent.personaId,
            msgText,
          );
          personaDrift[activeAgentId] = drift;
          if (drift.hasDrift) {
            this.onPersonaDrift?.(activeAgentId, agent.personaId, drift);
          }
        }
      }

      // Check if the agent called any tools
      if (Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0) {
        let delegatedTo: string | undefined;

        // Check for handoff tool call
        for (const tc of msg.tool_calls) {
          const fnName = tc.function.name;
          if (fnName.startsWith('transfer_to_')) {
            const targetId = fnName.replace('transfer_to_', '');
            if (this.agents.has(targetId)) {
              delegatedTo = targetId;

              // Parse handoff arguments
              let parsedArgs: {
                reason?: string;
                context_updates?: Record<string, unknown>;
              } = {};
              try {
                parsedArgs = JSON.parse(tc.function.arguments || '{}');
              } catch {
                parsedArgs = {};
              }

              if (parsedArgs.context_updates) {
                for (const [k, v] of Object.entries(
                  parsedArgs.context_updates,
                )) {
                  context.set(k, v);
                }
              }

              // Append handoff acknowledgment tool message
              history.push({
                role: 'tool',
                tool_call_id: tc.id,
                name: fnName,
                content: JSON.stringify({
                  status: 'transferred',
                  targetAgent: targetId,
                  reason: parsedArgs.reason || 'Delegated to specialist',
                }),
              });
              break;
            }
          }
        }

        // If handoff occurred, advance agent and continue
        if (delegatedTo) {
          handoffCount++;
          activeAgentId = delegatedTo;
          continue;
        }

        // Regular MCP tools execution
        const toolResults = await this.client.mcp.executeToolCalls(
          msg.tool_calls,
        );
        for (const tr of toolResults) {
          history.push(tr);
        }
        continue;
      }

      // No tool calls and no handoffs: final answer reached
      const finalContent =
        typeof msg.content === 'string'
          ? msg.content
          : Array.isArray(msg.content)
            ? (msg.content as ContentPart[])
                .filter((p) => p.type === 'text')
                .map((p) => p.text)
                .join('')
            : '';

      const endCost = this.client.getMetrics().estimatedCostUsd;
      const totalCostUsd = Number(Math.max(0, endCost - startCost).toFixed(6));

      return {
        content: finalContent,
        finalAgentId: activeAgentId,
        history,
        sharedContext: context.getAll(),
        totalSteps,
        totalHandoffs: handoffCount,
        agentSteps,
        totalCostUsd,
        agentSpendBreakdown,
        ...(Object.keys(personaDrift).length > 0 ? { personaDrift } : {}),
        ...(Object.keys(prunedEphemeralSkills).length > 0
          ? { prunedEphemeralSkills }
          : {}),
      };
    }

    // Hit max handoffs safeguard
    const lastMsg = history[history.length - 1];
    const endCost = this.client.getMetrics().estimatedCostUsd;
    const totalCostUsd = Number(Math.max(0, endCost - startCost).toFixed(6));
    return {
      content:
        typeof lastMsg?.content === 'string'
          ? lastMsg.content
          : 'Max handoffs reached.',
      finalAgentId: activeAgentId,
      history,
      sharedContext: context.getAll(),
      totalSteps,
      totalHandoffs: handoffCount,
      agentSteps,
      totalCostUsd,
      agentSpendBreakdown,
      ...(Object.keys(personaDrift).length > 0 ? { personaDrift } : {}),
      ...(Object.keys(prunedEphemeralSkills).length > 0
        ? { prunedEphemeralSkills }
        : {}),
    };
  }

  /**
   * Run the multi-agent swarm with real-time streaming events
   */
  public async *runStream(options: {
    messages?: ChatMessage[];
    task?: string;
    initialAgentId?: string;
    context?: Record<string, unknown>;
  }): AsyncGenerator<SwarmStreamEvent, void, undefined> {
    const context = new SwarmContext(options.context);
    let activeAgentId = options.initialAgentId || this.defaultAgentId;
    let handoffCount = 0;
    let totalSteps = 0;
    const agentSteps: Record<string, number> = {};
    const agentSpendBreakdown: Record<
      string,
      { costUsd: number; tokens: number }
    > = {};
    const personaDrift: Record<string, PersonaDriftResult> = {};
    const prunedEphemeralSkills: Record<string, string[]> = {};
    const startCost = this.client.getMetrics().estimatedCostUsd;
    const history: ChatMessage[] = options.messages
      ? [...options.messages]
      : [];
    if (options.task && history.length === 0) {
      history.push({ role: 'user', content: options.task });
    }

    while (handoffCount <= this.maxHandoffs) {
      const agent = this.agents.get(activeAgentId);
      if (!agent) {
        throw new Error(`Active agent "${activeAgentId}" not found in Swarm.`);
      }

      agentSteps[activeAgentId] = (agentSteps[activeAgentId] || 0) + 1;
      totalSteps++;

      yield {
        type: 'agent-start',
        agentId: activeAgentId,
        agentName: agent.name,
        step: totalSteps,
        handoffCount,
      };

      let baseInstructions = agent.instructions;
      if (agent.personaId && this.personaRegistry) {
        baseInstructions = this.personaRegistry.buildSystemPrompt(
          agent.personaId,
          agent.instructions,
        );
      }
      const systemContent = `${baseInstructions}\n\nYou are specialist: ${agent.name} (${agent.role}).${context.toPromptSection()}`;
      const stepMessages: ChatMessage[] = [
        { role: 'system', content: systemContent },
        ...history.filter((m) => m.role !== 'system'),
      ];

      const tools = this.compileAgentTools(agent);

      const req: CreateChatCompletionRequest = {
        model: agent.model || this.defaultModel || 'default',
        messages: stepMessages,
        tools: tools.length > 0 ? tools : undefined,
        thinkingBudget: agent.thinkingBudget,
        reasoningEffort: agent.reasoningEffort,
        thinkingLevel: agent.thinkingLevel,
        stream: true,
      };

      const stream = (await this.client.chat.completions.create(
        req,
      )) as AsyncIterable<UnifiedApiStreamChunk>;

      let contentAcc = '';
      let reasoningAcc = '';
      const toolCallsMap = new Map<
        number,
        { id: string; name: string; arguments: string }
      >();

      for await (const chunk of stream) {
        const choice = chunk.choices?.[0];
        if (!choice) continue;

        const delta = choice.delta;
        if (
          typeof delta.reasoning_content === 'string' &&
          delta.reasoning_content
        ) {
          reasoningAcc += delta.reasoning_content;
          yield {
            type: 'reasoning-delta',
            agentId: activeAgentId,
            reasoningDelta: delta.reasoning_content,
            chunk,
          };
        }

        if (typeof delta.content === 'string' && delta.content) {
          contentAcc += delta.content;
          yield {
            type: 'text-delta',
            agentId: activeAgentId,
            textDelta: delta.content,
            chunk,
          };
        }

        if (Array.isArray(delta.tool_calls)) {
          for (const tc of delta.tool_calls) {
            const idx = tc.index ?? 0;
            const existing = toolCallsMap.get(idx) || {
              id: '',
              name: '',
              arguments: '',
            };
            if (tc.id) existing.id = tc.id;
            if (tc.function?.name) existing.name += tc.function.name;
            if (tc.function?.arguments)
              existing.arguments += tc.function.arguments;
            toolCallsMap.set(idx, existing);
          }
        }
      }

      const assembledToolCalls: ToolCall[] = Array.from(toolCallsMap.entries())
        .sort(([a], [b]) => a - b)
        .map(([idx, tc]) => ({
          id: tc.id || `call_${totalSteps}_${idx}`,
          type: 'function' as const,
          function: {
            name: tc.name,
            arguments: tc.arguments || '{}',
          },
        }));

      const assistantMsg: ChatMessage = {
        role: 'assistant',
        content: contentAcc,
        reasoning_content: reasoningAcc || undefined,
        tool_calls:
          assembledToolCalls.length > 0 ? assembledToolCalls : undefined,
      };
      history.push(assistantMsg);

      // Evaluate persona lifecycle in streaming mode
      if (agent.personaId && this.personaRegistry) {
        const turnInfo = this.personaRegistry.consumeTurn(agent.personaId);
        if (turnInfo.prunedSkills.length > 0) {
          prunedEphemeralSkills[activeAgentId] = [
            ...(prunedEphemeralSkills[activeAgentId] || []),
            ...turnInfo.prunedSkills,
          ];
        }
        if (contentAcc) {
          const drift = this.personaRegistry.detectDrift(
            agent.personaId,
            contentAcc,
          );
          personaDrift[activeAgentId] = drift;
          if (drift.hasDrift) {
            this.onPersonaDrift?.(activeAgentId, agent.personaId, drift);
          }
        }
      }

      if (assembledToolCalls.length > 0) {
        yield {
          type: 'tool-call-start',
          agentId: activeAgentId,
          toolCalls: assembledToolCalls,
        };

        let delegatedTo: string | undefined;

        for (const tc of assembledToolCalls) {
          const fnName = tc.function.name;
          if (fnName.startsWith('transfer_to_')) {
            const targetId = fnName.replace('transfer_to_', '');
            if (this.agents.has(targetId)) {
              delegatedTo = targetId;

              let parsedArgs: {
                reason?: string;
                context_updates?: Record<string, unknown>;
              } = {};
              try {
                parsedArgs = JSON.parse(tc.function.arguments || '{}');
              } catch {
                parsedArgs = {};
              }

              if (parsedArgs.context_updates) {
                for (const [k, v] of Object.entries(
                  parsedArgs.context_updates,
                )) {
                  context.set(k, v);
                }
              }

              yield {
                type: 'handoff',
                fromAgentId: activeAgentId,
                toAgentId: targetId,
                reason: parsedArgs.reason || 'Delegated to specialist',
                contextUpdates: parsedArgs.context_updates,
              };

              history.push({
                role: 'tool',
                tool_call_id: tc.id,
                name: fnName,
                content: JSON.stringify({
                  status: 'transferred',
                  targetAgent: targetId,
                  reason: parsedArgs.reason || 'Delegated to specialist',
                }),
              });
              break;
            }
          }
        }

        if (delegatedTo) {
          handoffCount++;
          activeAgentId = delegatedTo;
          continue;
        }

        // Parallel regular tool execution
        const toolResults =
          await this.client.mcp.executeToolCalls(assembledToolCalls);
        for (const tr of toolResults) {
          history.push(tr);
        }

        yield {
          type: 'tool-call-result',
          agentId: activeAgentId,
          toolCalls: assembledToolCalls,
          results: toolResults,
        };
        continue;
      }

      // Completed successfully
      const endCost = this.client.getMetrics().estimatedCostUsd;
      const totalCostUsd = Number(Math.max(0, endCost - startCost).toFixed(6));

      const result: SwarmResult = {
        content: contentAcc,
        finalAgentId: activeAgentId,
        history,
        sharedContext: context.getAll(),
        totalSteps,
        totalHandoffs: handoffCount,
        agentSteps,
        totalCostUsd,
        agentSpendBreakdown,
        ...(Object.keys(personaDrift).length > 0 ? { personaDrift } : {}),
        ...(Object.keys(prunedEphemeralSkills).length > 0
          ? { prunedEphemeralSkills }
          : {}),
      };

      yield {
        type: 'done',
        result,
      };
      return;
    }

    // Max handoffs reached
    const endCost = this.client.getMetrics().estimatedCostUsd;
    const totalCostUsd = Number(Math.max(0, endCost - startCost).toFixed(6));

    const result: SwarmResult = {
      content: 'Max handoffs reached.',
      finalAgentId: activeAgentId,
      history,
      sharedContext: context.getAll(),
      totalSteps,
      totalHandoffs: handoffCount,
      agentSteps,
      totalCostUsd,
      ...(Object.keys(personaDrift).length > 0 ? { personaDrift } : {}),
      ...(Object.keys(prunedEphemeralSkills).length > 0
        ? { prunedEphemeralSkills }
        : {}),
    };

    yield {
      type: 'done',
      result,
    };
  }

  /**
   * Runs multiple specialist agents concurrently in parallel branches (Fan-Out),
   * and optionally synthesizes all branch outputs via an aggregator agent (Fan-In / Map-Reduce).
   */
  public async runParallel(
    options: SwarmParallelOptions,
  ): Promise<SwarmParallelResult> {
    const startTime = Date.now();
    const mode = options.mode ?? 'all_settled';
    const sharedContext = new SwarmContext(options.initialContext);

    // Normalize tasks
    const tasks: SwarmParallelAgentTask[] = options.tasks.map((t) => {
      if (typeof t === 'string') {
        return { agentId: t, prompt: options.prompt };
      }
      return {
        agentId: t.agentId,
        prompt: t.prompt ?? options.prompt,
        contextUpdates: t.contextUpdates,
      };
    });

    const branchPromises = tasks.map(
      async (task): Promise<SwarmParallelBranchResult> => {
        const agent = this.getAgent(task.agentId);
        const agentName = agent ? agent.name : task.agentId;

        if (!agent) {
          return {
            agentId: task.agentId,
            agentName,
            status: 'error',
            content: '',
            error: `Agent with ID "${task.agentId}" is not registered in the swarm.`,
            totalSteps: 0,
            costUsd: 0,
            history: [],
          };
        }

        // Branch context includes shared context + branch updates
        const branchContext = new SwarmContext({
          ...sharedContext.getAll(),
          ...(task.contextUpdates || {}),
        });

        const branchPrompt =
          task.prompt ?? 'Execute your assigned specialization.';

        try {
          const branchResult = await this.run({
            initialAgentId: task.agentId,
            ...(typeof branchPrompt === 'string'
              ? { task: branchPrompt }
              : { messages: branchPrompt }),
            context: branchContext.getAll(),
          });

          // Merge any branch context updates back using deep merge
          sharedContext.merge(branchResult.sharedContext, {
            deep: options.contextMergeStrategy !== 'last-write-wins',
            arrayStrategy: options.arrayStrategy ?? 'union',
            onConflict: options.onContextConflict
              ? (key, a, b) =>
                  options.onContextConflict?.(key, a, b, task.agentId)
              : undefined,
          });

          return {
            agentId: task.agentId,
            agentName,
            status: 'success',
            content: branchResult.content,
            totalSteps: branchResult.totalSteps,
            costUsd: branchResult.totalCostUsd,
            history: branchResult.history,
          };
        } catch (err) {
          if (mode === 'strict') {
            throw err;
          }
          return {
            agentId: task.agentId,
            agentName,
            status: 'error',
            content: '',
            error: err instanceof Error ? err.message : String(err),
            totalSteps: 0,
            costUsd: 0,
            history: [],
          };
        }
      },
    );

    const branches = await Promise.all(branchPromises);

    let totalCostUsd = branches.reduce((sum, b) => sum + b.costUsd, 0);
    let totalSteps = branches.reduce((sum, b) => sum + b.totalSteps, 0);
    let finalContent = '';
    let aggregated = false;

    // Optional Map-Reduce / Aggregator Step
    if (options.aggregatorAgentId) {
      const aggregator = this.getAgent(options.aggregatorAgentId);
      if (aggregator) {
        const synthesisPrompt = `You are the lead synthesizer for a multi-agent team.
Below are the individual outputs from our specialist agents who investigated the problem concurrently:

${branches
  .map(
    (b) =>
      `### Specialist [${b.agentName} (${b.agentId})]:\n${b.status === 'success' ? b.content : `[Error: ${b.error}]`}`,
  )
  .join('\n\n')}

Please review all specialist findings and provide a comprehensive, unified, and definitive response.`;

        const aggResult = await this.run({
          initialAgentId: options.aggregatorAgentId,
          task: synthesisPrompt,
          context: sharedContext.getAll(),
        });

        finalContent = aggResult.content;
        totalCostUsd += aggResult.totalCostUsd;
        totalSteps += aggResult.totalSteps;
        aggregated = true;

        for (const [k, v] of Object.entries(aggResult.sharedContext)) {
          sharedContext.set(k, v);
        }
      }
    }

    if (!finalContent) {
      // Default formatting if no aggregator is specified
      finalContent = branches
        .map(
          (b) =>
            `### [${b.agentName}]:\n${b.status === 'success' ? b.content : `Error: ${b.error}`}`,
        )
        .join('\n\n');
    }

    const durationMs = Date.now() - startTime;

    return {
      content: finalContent,
      branches,
      aggregated,
      aggregatorAgentId: options.aggregatorAgentId,
      totalCostUsd: Number(totalCostUsd.toFixed(6)),
      totalSteps,
      durationMs,
      sharedContext: sharedContext.getAll(),
    };
  }

  /**
   * Runs an Actor-Critic self-correcting feedback loop between a worker agent and a reviewer agent.
   */
  public async runActorCritic(
    options: ActorCriticOptions,
  ): Promise<ActorCriticResult> {
    const actor = this.getAgent(options.actorAgentId);
    if (!actor) {
      throw new Error(
        `Actor agent "${options.actorAgentId}" not found in swarm.`,
      );
    }
    const critic = this.getAgent(options.criticAgentId);
    if (!critic) {
      throw new Error(
        `Critic agent "${options.criticAgentId}" not found in swarm.`,
      );
    }

    const maxRevisions = options.maxRevisions ?? 3;
    const minScore = options.minScore ?? 0.8;
    const sharedContext = new SwarmContext(options.context);
    const revisions: ActorCriticRevision[] = [];
    const conversationHistory: ChatMessage[] = [];

    let totalCostUsd = 0;
    let currentActorDraft = '';
    let lastCriticFeedback = '';
    let approved = false;

    for (let iteration = 1; iteration <= maxRevisions; iteration++) {
      // Step A: Actor Turn
      let actorPrompt = '';
      if (iteration === 1) {
        actorPrompt =
          typeof options.task === 'string'
            ? options.task
            : options.task
                .map((m) =>
                  typeof m.content === 'string'
                    ? m.content
                    : JSON.stringify(m.content),
                )
                .join('\n');
      } else {
        actorPrompt = `Please revise your previous output based on the following critic evaluation:\n\n[CRITIC FEEDBACK]:\n${lastCriticFeedback}\n\n[PREVIOUS DRAFT]:\n${currentActorDraft}\n\nPlease generate a revised, complete solution addressing all feedback points.`;
      }

      const actorResult = await this.run({
        initialAgentId: options.actorAgentId,
        task: actorPrompt,
        context: sharedContext.getAll(),
      });

      totalCostUsd += actorResult.totalCostUsd;
      currentActorDraft = actorResult.content;
      conversationHistory.push(...actorResult.history);
      sharedContext.merge(actorResult.sharedContext);

      // Step B: Critic Turn
      const taskDescription =
        typeof options.task === 'string'
          ? options.task
          : JSON.stringify(options.task);
      const criticPrompt = `You are a strict, objective quality reviewer.
[ORIGINAL OBJECTIVE]:
${taskDescription}

[SUBMISSION TO REVIEW]:
${currentActorDraft}

Evaluate the submission against the objective for accuracy, completeness, and production readiness.
Format your response exactly as follows:
STATUS: <APPROVED or NEEDS_REVISION>
SCORE: <score between 0.0 and 1.0>
CRITIQUE: <concise, actionable feedback explaining why it passed or what needs improvement>`;

      const criticResult = await this.run({
        initialAgentId: options.criticAgentId,
        task: criticPrompt,
        context: sharedContext.getAll(),
      });

      totalCostUsd += criticResult.totalCostUsd;
      lastCriticFeedback = criticResult.content;
      conversationHistory.push(...criticResult.history);
      sharedContext.merge(criticResult.sharedContext);

      // Parse Critic output
      const statusMatch = /STATUS:\s*(APPROVED|NEEDS_REVISION)/i.exec(
        criticResult.content,
      );
      const scoreMatch = /SCORE:\s*([0-9.]+)/i.exec(criticResult.content);

      const parsedScore = scoreMatch
        ? Number.parseFloat(scoreMatch[1])
        : undefined;
      const explicitApproved =
        statusMatch?.[1]?.toUpperCase() === 'APPROVED' ||
        (parsedScore !== undefined && parsedScore >= minScore);

      approved = Boolean(explicitApproved);

      const revision: ActorCriticRevision = {
        iteration,
        actorOutput: currentActorDraft,
        criticFeedback: lastCriticFeedback,
        score: parsedScore,
        status: approved ? 'approved' : 'needs_revision',
        timestamp: Date.now(),
      };
      revisions.push(revision);

      options.onIteration?.({
        iteration,
        actorOutput: currentActorDraft,
        criticFeedback: lastCriticFeedback,
        approved,
        score: parsedScore,
      });

      if (approved) {
        break;
      }
    }

    if (options.recordDpo !== false && this.client?.distiller) {
      const firstDraft = revisions[0]?.actorOutput;
      if (firstDraft && currentActorDraft) {
        await this.client.distiller.recordDpo({
          prompt: options.task,
          chosen: currentActorDraft,
          rejected:
            firstDraft !== currentActorDraft
              ? firstDraft
              : revisions[0]?.criticFeedback || firstDraft,
          scoreChosen:
            revisions[revisions.length - 1]?.score ?? (approved ? 1.0 : 0.5),
          scoreRejected: revisions[0]?.score ?? 0.4,
          critique: revisions[0]?.criticFeedback,
          metadata: {
            actorAgentId: options.actorAgentId,
            criticAgentId: options.criticAgentId,
            totalRevisions: revisions.length,
            approved,
          },
        });
      }
    }

    return {
      finalContent: currentActorDraft,
      approved,
      totalRevisions: revisions.length,
      revisions,
      totalCostUsd: Number(totalCostUsd.toFixed(6)),
      actorAgentId: options.actorAgentId,
      criticAgentId: options.criticAgentId,
      history: conversationHistory,
      sharedContext: sharedContext.getAll(),
    };
  }

  /**
   * Executes a multi-model tournament deliberation across participating specialist agents,
   * applying semantic response clustering, majority/Borda voting, and dissent analysis.
   */
  public async runTournament(
    options: TournamentOptions,
  ): Promise<TournamentResult> {
    if (!options.agentIds || options.agentIds.length === 0) {
      throw new Error(
        'Tournament deliberation requires at least one participating agentId.',
      );
    }

    for (const agentId of options.agentIds) {
      if (!this.getAgent(agentId)) {
        throw new Error(`Tournament agent "${agentId}" not found in swarm.`);
      }
    }

    if (
      options.synthesizerAgentId &&
      !this.getAgent(options.synthesizerAgentId)
    ) {
      throw new Error(
        `Synthesizer agent "${options.synthesizerAgentId}" not found in swarm.`,
      );
    }

    options.onVoteProgress?.({
      phase: 'fan_out',
      completedAgents: 0,
      totalAgents: options.agentIds.length,
    });

    const sharedContext = new SwarmContext(options.context);
    const submissions: Record<string, { content: string; costUsd: number }> =
      {};
    const tournamentSubmissions: TournamentSubmission[] = [];
    const conversationHistory: ChatMessage[] = [];
    let totalCostUsd = 0;
    let completed = 0;

    // Phase 1: Fan-out execution across all candidate agents in parallel
    const agentPromises = options.agentIds.map(async (agentId) => {
      const runParams =
        typeof options.task === 'string'
          ? {
              initialAgentId: agentId,
              task: options.task,
              context: sharedContext.getAll(),
            }
          : {
              initialAgentId: agentId,
              messages: options.task,
              context: sharedContext.getAll(),
            };
      const runResult = await this.run(runParams);

      completed++;
      options.onVoteProgress?.({
        phase: 'fan_out',
        completedAgents: completed,
        totalAgents: options.agentIds.length,
      });

      return {
        agentId,
        result: runResult,
      };
    });

    const results = await Promise.all(agentPromises);

    for (const { agentId, result } of results) {
      totalCostUsd += result.totalCostUsd;
      conversationHistory.push(...result.history);
      sharedContext.merge(result.sharedContext);
      submissions[agentId] = {
        content: result.content,
        costUsd: result.totalCostUsd,
      };
      tournamentSubmissions.push({
        agentId,
        content: result.content,
        costUsd: result.totalCostUsd,
      });
    }

    // Phase 2: Semantic Clustering & Consensus Tallying
    options.onVoteProgress?.({ phase: 'clustering' });
    const engine = new TournamentConsensusEngine({
      strategy: options.votingStrategy,
      similarityThreshold: options.similarityThreshold,
      weights: options.weights,
    });

    options.onVoteProgress?.({ phase: 'tallying' });
    const consensus = await engine.evaluate(tournamentSubmissions);

    // Phase 3: Optional Synthesis Agent
    let synthesizedContent: string | undefined;
    if (options.synthesizerAgentId) {
      options.onVoteProgress?.({ phase: 'synthesis' });
      const taskStr =
        typeof options.task === 'string'
          ? options.task
          : options.task
              .map((m) =>
                typeof m.content === 'string'
                  ? m.content
                  : JSON.stringify(m.content),
              )
              .join('\n');

      const dissentSection =
        consensus.dissentingViews.length > 0
          ? `\n\n[DISSENTING PERSPECTIVES / MINORITY VIEWS]:\n${consensus.dissentingViews
              .map(
                (d, idx) =>
                  `Perspective ${idx + 1} (Agent: ${d.agentId}, Vote Share: ${(d.voteShare * 100).toFixed(1)}%):\n${d.content}`,
              )
              .join('\n\n')}`
          : '';

      const synthPrompt = `You are the master consensus synthesizer for the swarm.
[ORIGINAL OBJECTIVE]:
${taskStr}

[WINNING CONSENSUS PROPOSAL (Confidence: ${(consensus.confidence * 100).toFixed(1)}%)]:
${consensus.winningSolution}
${dissentSection}

Formulate a definitive, cohesive final output that builds upon the winning consensus while incorporating valid insights and addressing concerns raised in any dissenting views. Provide a clean, production-ready solution.`;

      const synthResult = await this.run({
        initialAgentId: options.synthesizerAgentId,
        task: synthPrompt,
        context: sharedContext.getAll(),
      });

      totalCostUsd += synthResult.totalCostUsd;
      conversationHistory.push(...synthResult.history);
      sharedContext.merge(synthResult.sharedContext);
      synthesizedContent = synthResult.content;
    }

    // Phase 4: Autonomous DPO Distillation
    if (
      options.recordDpo !== false &&
      this.client?.distiller &&
      consensus.dissentingViews.length > 0
    ) {
      const chosenText = synthesizedContent || consensus.winningSolution;
      const rejectedText = consensus.dissentingViews[0]?.content;

      if (chosenText && rejectedText && chosenText !== rejectedText) {
        await this.client.distiller.recordDpo({
          prompt: options.task,
          chosen: chosenText,
          rejected: rejectedText,
          scoreChosen: consensus.confidence,
          scoreRejected: Number((1.0 - consensus.confidence).toFixed(3)),
          critique: `Dissenting minority view from agent "${consensus.dissentingViews[0].agentId}" with vote share ${(consensus.dissentingViews[0].voteShare * 100).toFixed(1)}%`,
          metadata: {
            tournamentStrategy: consensus.strategy,
            winningAgentId: consensus.winningAgentId,
            dissentingAgentId: consensus.dissentingViews[0].agentId,
            totalSubmissions: consensus.totalSubmissions,
            confidence: consensus.confidence,
          },
        });
      }
    }

    return {
      winningSolution: consensus.winningSolution,
      winningAgentId: consensus.winningAgentId,
      strategy: consensus.strategy,
      confidence: consensus.confidence,
      clusters: consensus.clusters,
      dissentingViews: consensus.dissentingViews,
      scores: consensus.scores,
      totalCostUsd: Number(totalCostUsd.toFixed(6)),
      totalSubmissions: consensus.totalSubmissions,
      synthesizedContent,
      submissions,
      history: conversationHistory,
      sharedContext: sharedContext.getAll(),
    };
  }
}
